import json, glob, os
from collections import Counter
# For each task, find max consecutive identical tool call AND whether compaction/summary markers interleave, AND exit reason
for f in sorted(glob.glob("*.result.json")):
    tid=f.replace(".result.json","")
    r=json.load(open(f))
    exit_reason=r.get("agent",{}).get("exit_reason")
    steps=r.get("agent",{}).get("steps")
    mf=tid+".messages.json"
    if not os.path.exists(mf): continue
    msgs=json.load(open(mf))
    seq=[]
    compaction_idxs=[]
    for i,m in enumerate(msgs):
        if m["role"]=="user" and isinstance(m.get("content"),str) and ("PostCompaction" in m["content"] or "Earlier conversation summary" in m["content"]):
            compaction_idxs.append(i)
        if m["role"]=="assistant":
            for tc in (m.get("tool_calls") or []):
                seq.append((i,tc["function"]["arguments"]))
    # max consecutive identical
    maxrun=1;cur=1;runspan=(0,0);best=(0,0)
    for j in range(1,len(seq)):
        if seq[j][1]==seq[j-1][1]:
            cur+=1
            if cur>maxrun: maxrun=cur; best=(seq[j-1-(cur-2)][0] if False else seq[j][0], seq[j][0])
        else:
            cur=1
    if maxrun>=5 or exit_reason in ("budget_exceeded","error","loop_detected"):
        print(f"{tid[:22]:22} exit={str(exit_reason):16} steps={steps} maxIdenticalRun={maxrun} n_compaction={len(compaction_idxs)}")
EOF

